import{b as e,O as a,g as s,j as n}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"指标解读","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/metrics/index.md","filePath":"性能测试/1.Jmeter/06.指标解读.md","lastUpdated":1781755252000}'),d={name:"performance/jmeter/metrics/index.md"};function r(l,t,o,i,p,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="指标解读" tabindex="-1">指标解读 <a class="header-anchor" href="#指标解读" aria-label="Permalink to &quot;指标解读&quot;">​</a></h1><blockquote><p>压测跑完了，汇总报告里一排数字什么意思？这一章逐个解释，帮你一眼看出系统行不行。</p></blockquote><h2 id="核心指标速查" tabindex="-1">核心指标速查 <a class="header-anchor" href="#核心指标速查" aria-label="Permalink to &quot;核心指标速查&quot;">​</a></h2><p>打开汇总报告或聚合报告，你会看到这些列：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th style="text-align:center;">好的标准</th></tr></thead><tbody><tr><td>Samples（样本数）</td><td>总共发了多少个请求</td><td style="text-align:center;">—</td></tr><tr><td>Average（平均值）</td><td>平均响应时间（毫秒）</td><td style="text-align:center;"><strong>&lt; 500ms</strong></td></tr><tr><td>Median（中位数）</td><td>50% 请求的响应时间</td><td style="text-align:center;">&lt; 300ms</td></tr><tr><td>90% Line（P90）</td><td>90% 请求在此时间内完成</td><td style="text-align:center;">&lt; 1000ms</td></tr><tr><td>95% Line（P95）</td><td>95% 请求在此时间内完成</td><td style="text-align:center;">&lt; 1500ms</td></tr><tr><td>99% Line（P99）</td><td>99% 请求在此时间内完成</td><td style="text-align:center;">&lt; 3000ms</td></tr><tr><td>Min（最小值）</td><td>最快那次</td><td style="text-align:center;">—</td></tr><tr><td>Max（最大值）</td><td>最慢那次</td><td style="text-align:center;"><strong>&lt; 2000ms</strong></td></tr><tr><td>Std. Dev.（标准差）</td><td>响应时间的波动程度</td><td style="text-align:center;">越低越好</td></tr><tr><td>Error %（错误率）</td><td>失败请求占比</td><td style="text-align:center;"><strong>0%</strong></td></tr><tr><td>Throughput（吞吐量）</td><td>每秒处理请求数 (TPS)</td><td style="text-align:center;">越高越好</td></tr></tbody></table><blockquote><p><strong>平均值会骗人</strong>。想象 100 个请求，99 个 100ms、1 个 10 秒——平均值只有 199ms，看起来很好，但那 1 个用户已经摔键盘了。所以 <strong>P95/P99 比 Average 更重要</strong>。</p><p><strong>Std. Dev. 同样重要</strong>。平均值 200ms + 标准差 50ms = 性能稳定；平均值 200ms + 标准差 500ms = 响应时间忽快忽慢，同样有问题。</p><p>上面&quot;好的标准&quot;一列是参考值，实际要结合你的项目来定。比如实时交易系统的 P99 可能要 &lt; 500ms，后台报表系统的 P99 &lt; 5 秒就算不错。</p></blockquote><h2 id="什么是百分位线" tabindex="-1">什么是百分位线 <a class="header-anchor" href="#什么是百分位线" aria-label="Permalink to &quot;什么是百分位线&quot;">​</a></h2><p>&quot;95% Line = 1500ms&quot; 的意思是：<strong>100 个请求中，95 个在 1500ms 以内完成，剩下 5 个超过了。</strong></p><table tabindex="0"><thead><tr><th>百分位</th><th>反映什么</th></tr></thead><tbody><tr><td><strong>P50（中位数）</strong></td><td>典型用户的体验</td></tr><tr><td><strong>P90</strong></td><td>大多数用户的最差情况</td></tr><tr><td><strong>P95</strong></td><td>尾延迟的起点——这里开始要关注了</td></tr><tr><td><strong>P99</strong></td><td>极端情况——少数用户卡了很久</td></tr></tbody></table><blockquote><p>面试爱问：<strong>平均响应 300ms，P99 是 5 秒，系统好还是不好？</strong> 答案：不好。有 1% 的用户卡了 5 秒，说明系统在高并发下有严重瓶颈。</p></blockquote><h2 id="tps-与并发数的关系" tabindex="-1">TPS 与并发数的关系 <a class="header-anchor" href="#tps-与并发数的关系" aria-label="Permalink to &quot;TPS 与并发数的关系&quot;">​</a></h2><p>TPS（Throughput）是压测里最关键的容量指标。正常情况下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TPS = 并发用户数 ÷ 平均响应时间（秒）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：50 个用户，平均响应 200ms（0.2s）</span></span>
<span class="line"><span>TPS ≈ 50 ÷ 0.2 = 250</span></span></code></pre></div><p><strong>压测时怎么读 TPS 趋势</strong>：</p><table tabindex="0"><thead><tr><th>现象</th><th>说明</th></tr></thead><tbody><tr><td>TPS 随并发数线性增长</td><td>✅ 系统还有余力</td></tr><tr><td>TPS 增速放缓</td><td>⚠️ 接近瓶颈</td></tr><tr><td>TPS 不再增长甚至下降</td><td>❌ 已达上限</td></tr><tr><td>TPS 正常但 Error% 飙升</td><td>❌ 某些资源耗尽（连接池、队列满了）</td></tr></tbody></table><h2 id="apdex-应用性能指数" tabindex="-1">APDEX（应用性能指数） <a class="header-anchor" href="#apdex-应用性能指数" aria-label="Permalink to &quot;APDEX（应用性能指数）&quot;">​</a></h2><p>一个 0~1 的评分，综合衡量用户满意度：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APDEX = (满意数 + 容忍数 × 0.5) ÷ 总样本数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>满意   ≤ 500ms  （默认阈值，可调）</span></span>
<span class="line"><span>容忍   500ms ~ 1500ms</span></span>
<span class="line"><span>失望   &gt; 1500ms</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">APDEX</th><th>评级</th></tr></thead><tbody><tr><td style="text-align:center;">≥ 0.94</td><td>🟢 优秀</td></tr><tr><td style="text-align:center;">0.85~0.94</td><td>🟡 良好</td></tr><tr><td style="text-align:center;">0.70~0.85</td><td>🟠 一般</td></tr><tr><td style="text-align:center;">&lt; 0.70</td><td>🔴 不可接受</td></tr></tbody></table><blockquote><p>APDEX 在 JMeter HTML 报告的 Dashboard 首页就有，是最直观的&quot;一句话结论&quot;。</p></blockquote><h2 id="看报告的标准流程" tabindex="-1">看报告的标准流程 <a class="header-anchor" href="#看报告的标准流程" aria-label="Permalink to &quot;看报告的标准流程&quot;">​</a></h2><p>跑完压测，按这个顺序看报告，不会漏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Error%     → 不是 0%？先修报错</span></span>
<span class="line"><span>2. TPS        → 达到预期没有？</span></span>
<span class="line"><span>3. P95/P99    → 尾延迟可接受吗？</span></span>
<span class="line"><span>4. Average    → 整体水平如何</span></span>
<span class="line"><span>5. TPS 趋势   → 随时间平稳还是下滑？</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>P95/P99 比 Average 更重要</strong>——平均值掩盖尾延迟问题</li><li><strong>Error% 必须 0%</strong>——有报错先排查，别盲目相信其他指标</li><li><strong>TPS 趋势找拐点</strong>——拐点就是系统的性能上限</li><li><strong>APDEX 一句话结论</strong>——≥ 0.94 算优秀</li><li>看报告顺序：Error% → TPS → P95/P99 → Average → 趋势</li></ul>`,25)])])}const b=e(d,[["render",r]]);export{g as __pageData,b as default};
